module heap_subset_finder (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] valid_mask,\n    input [7:0] v0, v1, v2, v3, v4, v5, v6, v7,\n    input [2:0] p0, p1, p2, p3, p4, p5, p6, p7,\n    output reg [3:0] result,\n    output reg done\n);\n\n    // State definitions\n    localparam [3:0] S_IDLE            = 4'd0;\n    localparam [3:0] S_LOAD            = 4'd1;\n    localparam [3:0] S_ANC_START       = 4'd2;\n    localparam [3:0] S_ANC_SET         = 4'd3;\n    localparam [3:0] S_ANC_NEXT        = 4'd4;\n    localparam [3:0] S_CHECK_INIT      = 4'd5;\n    localparam [3:0] S_CHECK_SUBSET    = 4'd6;\n    localparam [3:0] S_CHECK_VALIDATE  = 4'd7;\n    localparam [3:0] S_CHECK_ILOOP     = 4'd8;\n    localparam [3:0] S_CHECK_JLOOP     = 4'd9;\n    localparam [3:0] S_CHECK_POPCNT    = 4'd10;\n    localparam [3:0] S_CHECK_UPDATE    = 4'd11;\n    localparam [3:0] S_CHECK_NEXT      = 4'd12;\n    localparam [3:0] S_DONE            = 4'd13;\n\n    // Internal registers\n    reg [3:0] state;\n    reg [7:0] v_reg [0:7];\n    reg [2:0] p_reg [0:7];\n    reg [7:0] valid_reg;\n    reg [7:0] subset;\n    reg [7:0] anc [0:7];\n    reg [3:0] max_size;\n    reg [3:0] j_idx;\n    reg [2:0] k_idx;\n    reg [3:0] i_idx;\n    reg [3:0] j_idx2;\n    reg invalid_flag;\n    reg [3:0] popcnt;\n    reg [3:0] bit_idx;\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= S_IDLE;\n            done <= 1'b0;\n            result <= 4'd0;\n            valid_reg <= 8'd0;\n            subset <= 8'd0;\n            max_size <= 4'd0;\n            invalid_flag <= 1'b0;\n            popcnt <= 4'd0;\n            j_idx <= 4'd0;\n            k_idx <= 3'd0;\n            i_idx <= 4'd0;\n            j_idx2 <= 4'd0;\n            bit_idx <= 4'd0;\n            // Array initializations\n            for (integer i = 0; i < 8; i = i + 1) begin\n                v_reg[i] <= 8'd0;\n                p_reg[i] <= 3'd0;\n                anc[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                S_IDLE: begin\n                    done <= 1'b0;\n                    if (start) state <= S_LOAD;\n                end\n                \n                S_LOAD: begin\n                    v_reg[0] <= v0;\n                    v_reg[1] <= v1;\n                    v_reg[2] <= v2;\n                    v_reg[3] <= v3;\n                    v_reg[4] <= v4;\n                    v_reg[5] <= v5;\n                    v_reg[6] <= v6;\n                    v_reg[7] <= v7;\n                    p_reg[0] <= p0;\n                    p_reg[1] <= p1;\n                    p_reg[2] <= p2;\n                    p_reg[3] <= p3;\n                    p_reg[4] <= p4;\n                    p_reg[5] <= p5;\n                    p_reg[6] <= p6;\n                    p_reg[7] <= p7;\n                    valid_reg <= valid_mask;\n                    state <= S_ANC_START;\n                    j_idx <= 4'd0;\n                end\n                \n                S_ANC_START: begin\n                    if (p_reg[j_idx] < 3'd7) begin\n                        k_idx <= p_reg[j_idx];\n                        state <= S_ANC_SET;\n                    end else begin\n                        j_idx <= j_idx + 4'd1;\n                        if (j_idx == 4'd7) state <= S_CHECK_INIT;\n                    end\n                end\n                \n                S_ANC_SET: begin\n                    anc[k_idx][j_idx] <= 1'b1;\n                    if (p_reg[k_idx] < 3'd7) begin\n                        k_idx <= p_reg[k_idx];\n                    end else begin\n                        j_idx <= j_idx + 4'd1;\n                        state <= (j_idx == 4'd7) ? S_CHECK_INIT : S_ANC_START;\n                    end\n                end\n                \n                S_CHECK_INIT: begin\n                    subset <= 8'b00000001;\n                    max_size <= 4'd0;\n                    state <= S_CHECK_SUBSET;\n                end\n                \n                S_CHECK_SUBSET: begin\n                    invalid_flag <= 1'b0;\n                    state <= S_CHECK_VALIDATE;\n                end\n                \n                S_CHECK_VALIDATE: begin\n                    if ((subset & ~valid_reg) != 8'd0) invalid_flag <= 1'b1;\n                    i_idx <= 4'd0;\n                    state <= S_CHECK_ILOOP;\n                end\n                \n                S_CHECK_ILOOP: begin\n                    if (i_idx >= 4'd8) begin\n                        if (!invalid_flag) state <= S_CHECK_POPCNT;\n                        else state <= S_CHECK_NEXT;\n                    end else begin\n                        if (subset[i_idx]) begin\n                            j_idx2 <= 4'd0;\n                            state <= S_CHECK_JLOOP;\n                        end else begin\n                            i_idx <= i_idx + 4'd1;\n                        end\n                    end\n                end\n                \n                S_CHECK_JLOOP: begin\n                    if (j_idx2 >= 4'd8) begin\n                        i_idx <= i_idx + 4'd1;\n                        state <= S_CHECK_ILOOP;\n                    end else begin\n                        if (subset[j_idx2] && (i_idx != j_idx2)) begin\n                            if (anc[i_idx][j_idx2] && (v_reg[i_idx] <= v_reg[j_idx2])) begin\n                                invalid_flag <= 1'b1;\n                                state <= S_CHECK_NEXT;\n                            end else begin\n                                j_idx2 <= j_idx2 + 4'd1;\n                            end\n                        end else begin\n                            j_idx2 <= j_idx2 + 4'd1;\n                        end\n                    end\n                end\n                \n                S_CHECK_POPCNT: begin\n                    popcnt <= 4'd0;\n                    bit_idx <= 4'd0;\n                    state <= S_CHECK_POPCNT;\n                end\n                \n                S_CHECK_POPCNT: begin\n                    if (bit_idx < 4'd8) begin\n                        if (subset[bit_idx]) popcnt <= popcnt + 4'd1;\n                        bit_idx <= bit_idx + 4'd1;\n                    end else begin\n                        state <= S_CHECK_UPDATE;\n                    end\n                end\n                \n                S_CHECK_UPDATE: begin\n                    if (popcnt > max_size) max_size <= popcnt;\n                    state <= S_CHECK_NEXT;\n                end\n                \n                S_CHECK_NEXT: begin\n                    subset <= subset + 8'd1;\n                    if (subset != 8'b11111111) begin\n                        state <= S_CHECK_SUBSET;\n                    end else begin\n                        state <= S_DONE;\n                    end\n                end\n                \n                S_DONE: begin\n                    result <= max_size;\n                    done <= 1'b1;\n                end\n                \n                default: state <= S_IDLE;\n            endcase\n        end\n    end\n\nendmodule